INSERT INTO tiendas (id, nombre, configuracion, creada_en) VALUES ('demo-tostadero', 'Tostadero Aurora', '{"tono": "cálido y cercano", "horario": "Lunes a sábado de 8:00 a 19:00. Domingos y festivos cerrado.", "bienvenida": "¡Hola! Soy el asistente de Tostadero Aurora ☕ ¿En qué te ayudo?", "reglas": ["Si preguntan por recomendaciones, pregunta primero cómo preparan el café en casa.", "Menciona la suscripción mensual cuando alguien compre café con frecuencia.", "Los precios están en pesos colombianos (COP) e incluyen IVA."]}', 0);
INSERT INTO conocimiento (id, tienda_id, tipo, titulo, contenido, datos_producto, actualizado_en) VALUES ('demo-p01', 'demo-tostadero', 'producto', 'Aurora Huila 250 g', 'Café de origen Huila, tueste medio. Notas a panela, durazno y chocolate con leche. En grano o molido.', '{"precio": 32000, "moneda": "COP", "categoria": "Café de origen"}', 0);
INSERT INTO conocimiento (id, tienda_id, tipo, titulo, contenido, datos_producto, actualizado_en) VALUES ('demo-p02', 'demo-tostadero', 'producto', 'Aurora Huila 500 g', 'Café de origen Huila, tueste medio, presentación de 500 g. Notas a panela, durazno y chocolate con leche.', '{"precio": 58000, "moneda": "COP", "categoria": "Café de origen"}', 0);
INSERT INTO conocimiento (id, tienda_id, tipo, titulo, contenido, datos_producto, actualizado_en) VALUES ('demo-p03', 'demo-tostadero', 'producto', 'Sierra Nevada 250 g', 'Café de la Sierra Nevada de Santa Marta, tueste medio-oscuro. Cuerpo alto, notas a cacao y nuez.', '{"precio": 34000, "moneda": "COP", "categoria": "Café de origen"}', 0);
INSERT INTO conocimiento (id, tienda_id, tipo, titulo, contenido, datos_producto, actualizado_en) VALUES ('demo-p04', 'demo-tostadero', 'producto', 'Nariño Altura 250 g', 'Café de Nariño cultivado a más de 2.000 m. Tueste claro, acidez brillante, notas a mandarina y flores.', '{"precio": 38000, "moneda": "COP", "categoria": "Café de origen"}', 0);
INSERT INTO conocimiento (id, tienda_id, tipo, titulo, contenido, datos_producto, actualizado_en) VALUES ('demo-p05', 'demo-tostadero', 'producto', 'Tolima Geisha 250 g', 'Microlote de variedad Geisha del Tolima. Tueste claro. Notas a jazmín, bergamota y miel. Edición limitada.', '{"precio": 72000, "moneda": "COP", "categoria": "Café especial"}', 0);
INSERT INTO conocimiento (id, tienda_id, tipo, titulo, contenido, datos_producto, actualizado_en) VALUES ('demo-p06', 'demo-tostadero', 'producto', 'Cauca Honey 250 g', 'Café del Cauca con proceso honey. Dulzor alto, notas a uva pasa y caramelo.', '{"precio": 40000, "moneda": "COP", "categoria": "Café especial"}', 0);
INSERT INTO conocimiento (id, tienda_id, tipo, titulo, contenido, datos_producto, actualizado_en) VALUES ('demo-p07', 'demo-tostadero', 'producto', 'Quindío Natural 250 g', 'Proceso natural (secado en cereza). Notas a fresa, vino tinto y chocolate oscuro.', '{"precio": 42000, "moneda": "COP", "categoria": "Café especial"}', 0);
INSERT INTO conocimiento (id, tienda_id, tipo, titulo, contenido, datos_producto, actualizado_en) VALUES ('demo-p08', 'demo-tostadero', 'producto', 'Mezcla de la Casa 500 g', 'Mezcla de cafés del Huila y Tolima, tueste medio. Equilibrada, ideal para el día a día.', '{"precio": 45000, "moneda": "COP", "categoria": "Mezclas"}', 0);
INSERT INTO conocimiento (id, tienda_id, tipo, titulo, contenido, datos_producto, actualizado_en) VALUES ('demo-p09', 'demo-tostadero', 'producto', 'Mezcla Espresso 500 g', 'Mezcla de tueste oscuro pensada para espresso y bebidas con leche. Crema densa, notas a cacao.', '{"precio": 48000, "moneda": "COP", "categoria": "Mezclas"}', 0);
INSERT INTO conocimiento (id, tienda_id, tipo, titulo, contenido, datos_producto, actualizado_en) VALUES ('demo-p10', 'demo-tostadero', 'producto', 'Descafeinado Suave 250 g', 'Café del Huila descafeinado con proceso de agua de montaña, sin químicos. Notas a caramelo.', '{"precio": 36000, "moneda": "COP", "categoria": "Mezclas"}', 0);
INSERT INTO conocimiento (id, tienda_id, tipo, titulo, contenido, datos_producto, actualizado_en) VALUES ('demo-p11', 'demo-tostadero', 'producto', 'Cold Brew Concentrado 1 L', 'Concentrado de café en frío listo para mezclar con agua o leche (1 parte de café por 2 de agua). Refrigerado, dura 10 días.', '{"precio": 30000, "moneda": "COP", "categoria": "Bebidas listas"}', 0);
INSERT INTO conocimiento (id, tienda_id, tipo, titulo, contenido, datos_producto, actualizado_en) VALUES ('demo-p12', 'demo-tostadero', 'producto', 'Prensa francesa 600 ml', 'Prensa francesa de vidrio borosilicato y acero inoxidable, 600 ml (3 tazas).', '{"precio": 85000, "moneda": "COP", "categoria": "Métodos"}', 0);
INSERT INTO conocimiento (id, tienda_id, tipo, titulo, contenido, datos_producto, actualizado_en) VALUES ('demo-p13', 'demo-tostadero', 'producto', 'Chemex 6 tazas', 'Cafetera Chemex clásica de 6 tazas con collar de madera.', '{"precio": 210000, "moneda": "COP", "categoria": "Métodos"}', 0);
INSERT INTO conocimiento (id, tienda_id, tipo, titulo, contenido, datos_producto, actualizado_en) VALUES ('demo-p14', 'demo-tostadero', 'producto', 'V60 cerámica', 'Gotero V60 de cerámica tamaño 02, para 1 a 4 tazas.', '{"precio": 95000, "moneda": "COP", "categoria": "Métodos"}', 0);
INSERT INTO conocimiento (id, tienda_id, tipo, titulo, contenido, datos_producto, actualizado_en) VALUES ('demo-p15', 'demo-tostadero', 'producto', 'AeroPress Original', 'Cafetera AeroPress con 350 filtros de papel incluidos.', '{"precio": 190000, "moneda": "COP", "categoria": "Métodos"}', 0);
INSERT INTO conocimiento (id, tienda_id, tipo, titulo, contenido, datos_producto, actualizado_en) VALUES ('demo-p16', 'demo-tostadero', 'producto', 'Moka italiana 6 tazas', 'Cafetera moka de aluminio para estufa, 6 tazas.', '{"precio": 120000, "moneda": "COP", "categoria": "Métodos"}', 0);
INSERT INTO conocimiento (id, tienda_id, tipo, titulo, contenido, datos_producto, actualizado_en) VALUES ('demo-p17', 'demo-tostadero', 'producto', 'Filtros de papel V60 x100', 'Filtros de papel blanco para V60 tamaño 02, paquete de 100.', '{"precio": 28000, "moneda": "COP", "categoria": "Accesorios"}', 0);
INSERT INTO conocimiento (id, tienda_id, tipo, titulo, contenido, datos_producto, actualizado_en) VALUES ('demo-p18', 'demo-tostadero', 'producto', 'Molino manual de cerámica', 'Molino manual con muelas cerámicas y molienda ajustable, de fino para espresso a grueso para prensa.', '{"precio": 160000, "moneda": "COP", "categoria": "Accesorios"}', 0);
INSERT INTO conocimiento (id, tienda_id, tipo, titulo, contenido, datos_producto, actualizado_en) VALUES ('demo-p19', 'demo-tostadero', 'producto', 'Báscula con temporizador', 'Báscula digital de 0,1 g con temporizador, ideal para métodos de filtrado.', '{"precio": 110000, "moneda": "COP", "categoria": "Accesorios"}', 0);
INSERT INTO conocimiento (id, tienda_id, tipo, titulo, contenido, datos_producto, actualizado_en) VALUES ('demo-p20', 'demo-tostadero', 'producto', 'Tetera cuello de cisne 1 L', 'Tetera de acero inoxidable con pico de cuello de cisne para verter con precisión. Apta para estufa.', '{"precio": 135000, "moneda": "COP", "categoria": "Accesorios"}', 0);
INSERT INTO conocimiento (id, tienda_id, tipo, titulo, contenido, datos_producto, actualizado_en) VALUES ('demo-p21', 'demo-tostadero', 'producto', 'Taza Aurora 300 ml', 'Taza de cerámica artesanal hecha en Ráquira con el logo de Aurora.', '{"precio": 35000, "moneda": "COP", "categoria": "Accesorios"}', 0);
INSERT INTO conocimiento (id, tienda_id, tipo, titulo, contenido, datos_producto, actualizado_en) VALUES ('demo-p22', 'demo-tostadero', 'producto', 'Kit de inicio V60', 'Incluye V60 de cerámica, 100 filtros y Aurora Huila 250 g. Ahorra frente a comprar por separado.', '{"precio": 140000, "moneda": "COP", "categoria": "Kits"}', 0);
INSERT INTO conocimiento (id, tienda_id, tipo, titulo, contenido, actualizado_en) VALUES ('demo-f01', 'demo-tostadero', 'faq', 'Horario de atención', 'Atendemos de lunes a sábado de 8:00 a 19:00. Domingos y festivos estamos cerrados, pero la tienda en línea recibe pedidos todos los días.', 0);
INSERT INTO conocimiento (id, tienda_id, tipo, titulo, contenido, actualizado_en) VALUES ('demo-f02', 'demo-tostadero', 'faq', 'Dirección de la tienda física', 'Estamos en la Calle 10 #43-21, barrio El Poblado, Medellín. Puedes recoger tu pedido allí sin costo.', 0);
INSERT INTO conocimiento (id, tienda_id, tipo, titulo, contenido, actualizado_en) VALUES ('demo-f03', 'demo-tostadero', 'faq', 'Envíos', 'Enviamos a todo el país con transportadora. En Medellín y el área metropolitana el envío llega en 24 horas hábiles. En otras ciudades tarda de 2 a 4 días hábiles.', 0);
INSERT INTO conocimiento (id, tienda_id, tipo, titulo, contenido, actualizado_en) VALUES ('demo-f04', 'demo-tostadero', 'faq', 'Costo de envío', 'El envío en Medellín cuesta 8.000 COP y a otras ciudades 15.000 COP. Las compras desde 150.000 COP tienen envío gratis.', 0);
INSERT INTO conocimiento (id, tienda_id, tipo, titulo, contenido, actualizado_en) VALUES ('demo-f05', 'demo-tostadero', 'faq', 'Medios de pago', 'Aceptamos tarjeta débito y crédito, PSE, Nequi, Daviplata y efectivo en la tienda física. El pago contra entrega solo está disponible en Medellín.', 0);
INSERT INTO conocimiento (id, tienda_id, tipo, titulo, contenido, actualizado_en) VALUES ('demo-f06', 'demo-tostadero', 'faq', 'Molienda a pedido', 'Todos nuestros cafés se pueden pedir en grano o molidos. Molemos según tu método: espresso, moka, V60, Chemex, AeroPress o prensa francesa. Solo indícalo al hacer el pedido.', 0);
INSERT INTO conocimiento (id, tienda_id, tipo, titulo, contenido, actualizado_en) VALUES ('demo-f07', 'demo-tostadero', 'faq', 'Fecha de tueste', 'Tostamos cada semana en pequeños lotes. Cada bolsa trae la fecha de tueste y recomendamos consumirla en las 6 semanas siguientes.', 0);
INSERT INTO conocimiento (id, tienda_id, tipo, titulo, contenido, actualizado_en) VALUES ('demo-f08', 'demo-tostadero', 'faq', 'Suscripción mensual', 'Con la suscripción mensual recibes cada mes 500 g de café (puedes elegir origen o dejar que te sorprendamos) por 52.000 COP con envío incluido. Puedes pausarla o cancelarla cuando quieras.', 0);
INSERT INTO conocimiento (id, tienda_id, tipo, titulo, contenido, actualizado_en) VALUES ('demo-f09', 'demo-tostadero', 'faq', 'Recomendación para principiantes', 'Si estás empezando, recomendamos la Mezcla de la Casa o el Aurora Huila, que son equilibrados y fáciles de preparar en cualquier método.', 0);
INSERT INTO conocimiento (id, tienda_id, tipo, titulo, contenido, actualizado_en) VALUES ('demo-f10', 'demo-tostadero', 'faq', 'Cómo conservar el café', 'Guarda el café en su bolsa con válvula, bien cerrada, en un lugar fresco y oscuro. No lo guardes en la nevera porque absorbe humedad y olores.', 0);
INSERT INTO conocimiento (id, tienda_id, tipo, titulo, contenido, actualizado_en) VALUES ('demo-f11', 'demo-tostadero', 'faq', 'Ventas al por mayor', 'Vendemos al por mayor a cafeterías, oficinas y restaurantes desde 5 kg al mes. Para cotizar, pide hablar con el equipo comercial.', 0);
INSERT INTO conocimiento (id, tienda_id, tipo, titulo, contenido, actualizado_en) VALUES ('demo-f12', 'demo-tostadero', 'faq', 'Contacto', 'Puedes escribirnos por este chat o al correo hola@tostaderoaurora.example. Respondemos en horario de atención.', 0);
INSERT INTO conocimiento (id, tienda_id, tipo, titulo, contenido, actualizado_en) VALUES ('demo-f13', 'demo-tostadero', 'politica', 'Cambios y devoluciones', 'Los métodos y accesorios tienen 30 días para cambio o devolución si están sin usar y en su empaque original. Por higiene, el café abierto no tiene devolución.', 0);
INSERT INTO conocimiento (id, tienda_id, tipo, titulo, contenido, actualizado_en) VALUES ('demo-f14', 'demo-tostadero', 'politica', 'Garantía de métodos y accesorios', 'Los métodos y accesorios tienen 6 meses de garantía por defectos de fábrica. No cubre golpes ni mal uso.', 0);
INSERT INTO conocimiento (id, tienda_id, tipo, titulo, contenido, actualizado_en) VALUES ('demo-f15', 'demo-tostadero', 'politica', 'Producto llegó en mal estado', 'Si tu pedido llega dañado o incompleto, escríbenos en las 48 horas siguientes con fotos y te enviamos el reemplazo sin costo.', 0);
INSERT INTO conocimiento (id, tienda_id, tipo, titulo, contenido, actualizado_en) VALUES ('demo-f16', 'demo-tostadero', 'politica', 'Disponibilidad de productos', 'Algunos cafés especiales se agotan por temporada. La disponibilidad exacta se confirma con la tienda al momento de hacer el pedido.', 0);
